INSERT INTO `deliveries` VALUES (1,'Самовывоз','Бесплатно, по адресу: г. Минск, ул. Тимирязева, 129/1 (Продовольственный центр), 2 этаж, павильон №17. вторник-воскресенье с 8.30 до 17.00, понедельник- выходной.',1000,1,NULL,NULL),(2,'Доставка по Минску в пределах МКАД','При заказе до 12.00 доставка осуществляется в день заказа. При заказе после 12.00 - на следующий день.',1000,1,NULL,NULL),(3,'Доставка в регионы Беларуси','Службой доставки, от 1 до 3 дней в зависимости от региона. Возможна доставка Европочтой. Стоимость доставки от 10 до 35 бел.руб. (зависит от региона доставки и габаритов товара)',1000,1,NULL,NULL);
